/** Alexis Mac Allister — Signature: "setting the tempo" (signature card). THE MOMENT: the World Cup final, Argentina 3–3 France (Argentina
 * won 4–2 on penalties), Lusail Stadium, Qatar, 18 December 2022, 36th minute: Argentina's second goal. Argentina win the ball back, Messi
 * flicks it first time to Julián Álvarez on the right, Álvarez at once plays Mac Allister in behind as he sprints from midfield into the
 * space the French centre-backs have left, and Mac Allister, arriving at the box, chooses the extra pass across to Ángel Di María, who
 * finishes with his left foot past Hugo Lloris. An iconic-play riso film (RisoStory, chapters mode): a 1:1 reconstruction from WRITTEN
 * accounts (we cannot watch the footage), printed as a riso sheet.
 *
 * WHY THIS MOMENT: Mac Allister's entry in lib/town/iconicPlays.json is a signature trait (kind "signature", template through_ball_assist,
 * lesson "Slow the game with safe passes, then speed it up with one quick forward pass"). This is his most famous contribution, it is the
 * "speed it up" half of the trait at its best (after a calm first half of Argentine possession, three quick forward passes in a few
 * seconds and a goal), and the written sources describe the play itself (who passed to whom, from which side, the run, the extra pass,
 * the finish), so the match chapters stage it. The lesson's "slow the game with safe passes" half is NOT claimed for this move: it is
 * taught only in the last chapter, a plainly separate "Your turn" demonstration on a daytime training pitch with young players in training
 * bibs (no named players, no match). The Di María films (if any) are not this one; no other film in lib/plays/riso stages this goal
 * (checked 24 Sep 2026), and this film's cameras follow the PASSER: a high chase camera behind Argentina's counter, then a low camera
 * behind Mac Allister's right shoulder — never behind the finisher or the goal.
 *
 * SOURCES (cached under scratchpad/films/src-cache, read 24 Sep 2026):
 *  - Wikipedia, "2022 FIFA World Cup final" (raw wikitext: date, venue, 18:00 kick-off, line-ups and numbers, the kit templates; "In the
 *    36th minute, Di Maria finished a sweeping Argentina counter-attack to make it 2–0, shooting with his left foot over the goalkeeper to
 *    the right corner of the net after a pass from Alexis Mac Allister from the right")  https://en.wikipedia.org/wiki/2022_FIFA_World_Cup_final
 *  - Wikipedia (es), "Final de la Copa Mundial de Fútbol de 2022" (the sequence: Mbappé's threat, Molina's cover, Martínez's clearance,
 *    Upamecano's header back under Álvarez's pressure; Messi receives with his back to goal, controls with his left and, before it touches
 *    the ground, flicks it with his left ankle to Álvarez open on the right; Mac Allister "ya había partido disparado desde mitad de cancha"
 *    into the space left by the French centre-backs; Álvarez plays him in; arriving at the box he chooses an extra pass to the left for
 *    Di María, alone and unmarked; the finish past Lloris; the Argentina kit with BLACK shorts)
 *    https://es.wikipedia.org/wiki/Final_de_la_Copa_Mundial_de_F%C3%BAtbol_de_2022
 *  - Infobae, "Así fue el golazo de Ángel Di María: la secuencia del 2 a 0 de Argentina contra Francia en la final del mundo" (18 Dec 2022:
 *    the move "began with Nahuel Molina's touch", who had seen Mac Allister "alone and with his back to goal near halfway"; Messi a few
 *    metres ahead, also back to goal; "Él podría haber rematado. Eligió dar un pase extra"; Koundé could not intercept Mac Allister's pass;
 *    Lloris went down low; Di María finished across goal with the inside of his LEFT foot into the far corner)
 *    https://www.infobae.com/deportes/2022/12/18/asi-fue-el-golazo-de-angel-di-maria-la-secuencia-del-2-a-0-de-argentina-contra-francia-en-la-final-del-mundo/
 *  - The Guardian, match report (18 Dec 2022): "Messi fired a flowing move with a flick to Julián Álvarez, who immediately got Alexis Mac
 *    Allister running. Di María took off, too, on the other side and Mac Allister's low crossfield ball was made to measure."
 *    https://www.theguardian.com/football/2022/dec/18/world-cup-final-argentina-france-match-report
 *  - BBC Sport, Phil McNulty (18 Dec 2022): "a magnificent counter-attack that ended with Brighton's Alexis Mac Allister setting up Di Maria"
 *    https://www.bbc.co.uk/sport/football/63932622
 *  - FIFA Training Centre, "Post Match Summary Report — Argentina v France, Final" (official event data: 35', DI MARIA Angel, On Target –
 *    Goal, LEFT FOOT, delivery Pass; Mac Allister No. 20, subbed 116')  https://www.fifatrainingcentre.com/media/native/world-cup-2022/report_128083.pdf
 * CONFIRMED by those accounts: the date, Lusail Stadium, an evening kick-off (18:00 local, so the 36th minute is under floodlights); Argentina
 * already 1–0 up (Messi's penalty); the goal came from a counter after Argentina won the ball back; Molina's pass began it; Messi's
 * first-time left-foot flick to Álvarez, open on the right; Álvarez at once played Mac Allister in behind; Mac Allister's sprint from
 * midfield into the space between the French centre-backs; his low pass from the right across to Di María, arriving unmarked on the left;
 * Koundé failed to cut it out; Lloris went down; Di María's left-foot finish across goal into the far (right) corner; 2–0. KITS: Argentina
 * in the sky-blue and white stripes with BLACK shorts (printed navy) and white socks; France in navy shirts and navy shorts. Numbers:
 * Mac Allister 20, Di María 11, Messi 10, Álvarez 9, Molina 26; France Lloris 1, Koundé 5, Varane 4, Upamecano 18, Tchouaméni 8.
 * INFERRED (illustrative, kept out of the narration): every position, run speed and timing between those beats; exactly how Molina's ball
 * reached Messi (drawn as a pass into Mac Allister, who lays it off first time to Messi — the accounts put both players back to goal near
 * halfway, "on the same line", and are not explicit about that touch); the direction of play on screen (Argentina attacking right, so
 * their right wing is the near touchline); the passing foot of Mac Allister (right) and Álvarez (right); Messi's control-and-flick pose;
 * Di María's touch before the shot; Lloris's shape (a low spread to his left) and his kit colour (a yellow screen; not verified); the
 * French socks (navy; sources disagree); the referee's kit (yellow); the other players' positions; the crowd colours; the Lusail bowl
 * (a round two-tier bowl under a roof ring with a floodlight band); the Al Hilm ball print; the celebration; camera placements and lenses.
 *
 * FRAMING (the TV broadcast, full-sheet card window 1.45:1 down to square, never sheet.safe; never top-down): 1 = live, the high main-stand
 * camera panning with the counter from halfway to the goal, near real time; 2 = slow replay from a high chase camera behind Argentina's
 * attack (≈ 12 m up, looking up the pitch): Messi's flick, Mac Allister's sprint (his yellow ring and run line), the space between the
 * defenders lit on the grass, Álvarez's pass arrow into it; 3 = slow replay from a low camera behind Mac Allister's right shoulder at the
 * edge of the box: the shot he could have taken (a pale dashed line), his look up (sight line), the pass across (traced), Koundé's miss,
 * Di María's left foot, the net; 4 = the lesson, a separate demonstration on a daytime training pitch: two calm, safe side passes (blue,
 * dashed, slow), a gap opens between two defenders (lit yellow), then ONE quick forward pass through it (bold yellow, speed lines) to a
 * runner. All figures are the shared riso athlete (lib/plays/riso/athlete.ts), routed through ONE adapter, drawPlayer(). Scenes read only
 * (t); every action keys off cue times, so the recorded voice (withTiming) re-times the film; every random value is seeded. */
import {withTiming,type NarrationTiming} from './timing';
import type {Sheet} from '../../paths/riso/sheet';
import {type RisoStory,type Scene,type Chapter,playChapters} from '../../paths/riso/story';
import {apertureDisc} from '../../paths/riso/passage';
import {TAU,twos,sm,key,clamp,lerp,rng,hash,blob,polyPath,ribbon,rectPath,easeOut,easeOutBack,easeInOutSine,linear,type Pt} from '../../paths/riso/motion';
import {sparkBurst,laneArrow} from '../../paths/riso/shapes';
import {drawAthlete,motionSmear,solve,runCycle,dribble,backpedal,strike,lunge,keeperSet,keeperDive,celebrate,stand,posed,blendPose,keyPoses,
 STRIKE_CONTACT,type Pose,type AthleteStyle,type InkFill,type Place,type Projector,type V3,type DrawResult} from './athlete';

// ---------------------------------------------------------------- narration + timing
/** The narration (script.json mirrors it). Cue `words` are the match keys for the voice's word onsets; their `at` and each chapter's
 * `seconds` are ESTIMATES (≈ .2 s a word + .021 s a letter + punctuation pauses) until the Kokoro voice exists. Every cue starts with a
 * plain ASCII word (Kokoro splits contractions; accents are stripped by the matcher). */
const SCRIPT:{label:string;text:string;tail:number;cues:string[]}[]=[
 {label:'The counter, live',text:'Lusail, 2022, the World Cup final. Argentina win it back. Messi flicks it to Julián Álvarez, who sends Alexis Mac Allister racing forward. He passes across to Di María, who scores!',tail:2.2,
  cues:['Lusail','the World Cup final','Argentina win','Messi flicks','who sends','Alexis Mac Allister','racing forward','He passes','across to','who scores']},
 {label:'Watch his run',text:'Watch again from behind. Mac Allister sprints into the space between the defenders, and Álvarez finds him.',tail:1.4,
  cues:['Watch again','Mac Allister sprints','into the space','between the defenders','and Álvarez','finds him']},
 {label:'The extra pass',text:'He could shoot, but he looks up and finds the free man. Di María finishes with his left foot!',tail:2,
  cues:['He could shoot','but he looks up','and finds','the free man','Di María finishes','with his left foot']},
 {label:'Your turn',text:'Your turn: keep the ball with calm, safe passes. When a gap opens, speed it up with one quick pass forward!',tail:1.9,
  cues:['Your turn','keep the ball','calm, safe passes','When a gap opens','speed it up','one quick pass','forward']},
];
/** VOICE: the lead runs scripts/plays/kokoro-narrate.py mac-allister-signature, which writes timing.json next to script.json. Then add
 *   import timingJson from '../../../public/plays/narration/mac-allister-signature/timing.json';
 * and pass `timingJson as NarrationTiming` here: withTiming swaps in the clips, chapter lengths and word onsets and the film re-times itself. */
import timingJson from '../../../public/plays/narration/mac-allister-signature/timing.json';
const VOICE:NarrationTiming|null=timingJson as NarrationTiming;
/** provisional word onsets: .2 s + .021 s a letter per word, pauses after , : . ! ? */
function estimate(text:string,cues:string[],tail:number){
 const words=[...text.matchAll(/\S+/g)],on:number[]=[];let t=.2;
 for(const m of words){on.push(t);const w=m[0];t+=.2+.021*w.replace(/[^a-z0-9]/gi,'').length;if(/[,;:]$/.test(w))t+=.18;if(/[.!?]$/.test(w))t+=.34;}
 let from=0;
 const cs=cues.map(c=>{const k=text.indexOf(c,from);if(k<0)throw new Error('mac-allister: cue "'+c+'" not in the narration');from=k+c.length;const wi=words.findIndex(m=>(m.index??0)+m[0].length>k);return{at:+on[wi].toFixed(2),words:c};});
 return{seconds:+(t+tail).toFixed(2),cues:cs};
}
const CHAPTERS:Chapter[]=withTiming(SCRIPT.map(c=>{const e=estimate(c.text,c.cues,c.tail);return{label:c.label,narration:c.text,seconds:e.seconds,cues:e.cues};}),VOICE);
/** onset of the cue whose words start with w in chapter i (throws on a typo, so a retime can never silently desync) */
const CUEW=(i:number,w:string)=>{const c=CHAPTERS[i].cues.find(q=>q.words.startsWith(w));if(!c)throw new Error('mac-allister: cue '+w);return c.at;};
const SECS=(i:number)=>CHAPTERS[i].seconds;
/** key() needs increasing times: push each key at least `gap` after the previous one (real voice timings can crowd authored offsets) */
function mono(K:[number,number][],gap=.05):[number,number][]{const o:[number,number][]=[];for(const[t,v] of K)o.push([o.length?Math.max(t,o[o.length-1][0]+gap):t,v]);return o;}

// ---------------------------------------------------------------- inks, small helpers
const Y='yellow',R='red',B='blue',K='navy';
const lerp3=(a:V3,b:V3,u:number):V3=>[lerp(a[0],b[0],u),lerp(a[1],b[1],u),lerp(a[2],b[2],u)];
const wrapA=(a:number)=>{a=(a+Math.PI)%TAU;if(a<0)a+=TAU;return a-Math.PI;};
const lerpA=(a:number,b:number,u:number)=>a+wrapA(b-a)*clamp(u);
/** heading of a ground direction as an athlete yaw (yaw 0 faces +X, + turns left toward −Z) */
const yawOf=(dx:number,dz:number)=>Math.atan2(-dz,dx);
const bump=(a:number,b:number,t:number)=>t<=a||t>=b?0:Math.sin(Math.PI*(t-a)/(b-a));
/** The film plays inside the player card's picture window (~1566 × 1080 units): world (x,y) on the CANVAS centre at z0 units per world unit
 * (the engine's arrival scale is kept, so passages and seams behave exactly as in the stories). Full-sheet framing, never sheet.safe. */
function cam(s:Sheet,x:number,y:number,z0:number,r=0){const z=z0*Math.min(1,Math.pow(s.W/1566,.75)),k=z*s.arrival;s.camera(x-(s.W/2-s.cx)/k,y-(s.H/2-s.cy)/k,z/s.fit,r);return z;}
type View={hx:number;hy:number};
const view=(s:Sheet,z:number):View=>({hx:s.W/(2*z*.68)+60,hy:s.H/(2*z*.68)+60});
const frame=(s:Sheet)=>view(s,cam(s,0,0,1));

// ---------------------------------------------------------------- the TV camera: a right-handed 3D projection of the pitch
/** Pitch metres (right-handed, like athlete.ts): X along the length (Argentina attack +X, France's goal line at X = 105, the right of the
 * main camera), Y up, Z across (0 = the middle, +34 = the near touchline under the main-stand camera). A figure facing +X has its right at
 * +Z, so Argentina's RIGHT wing (Molina, Álvarez, Mac Allister's run) is the near side and Di María's LEFT wing the far side; the shot
 * goes across goal to the +Z ("right") corner. */
type Cam=Projector&{C:V3;F:number;f:V3;r:V3;u:V3};
const NEAR=.4;
const sub3=(a:V3,b:V3):V3=>[a[0]-b[0],a[1]-b[1],a[2]-b[2]];
const dot3=(a:V3,b:V3)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
const nrm3=(a:V3):V3=>{const l=Math.hypot(a[0],a[1],a[2])||1;return[a[0]/l,a[1]/l,a[2]/l];};
const cross3=(a:V3,b:V3):V3=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
function look(C:V3,T:V3,F:number):Cam{const f=nrm3(sub3(T,C)),r=nrm3(cross3(f,[0,1,0])),u=cross3(r,f);
 return{C,F,f,r,u,eye:C,
  project(p:V3):[number,number,number]{const d=sub3(p,C),z=Math.max(NEAR,dot3(d,f));return[F*dot3(d,r)/z,-F*dot3(d,u)/z,z];},
  scale(p:V3){return F/Math.max(NEAR,dot3(sub3(p,C),f));}};}
function toCam(c:Cam,P:V3):V3{const d=sub3(P,c.C);return[dot3(d,c.r),dot3(d,c.u),dot3(d,c.f)];}
const scr=(c:Cam,q:V3):Pt=>[c.F*q[0]/q[2],-c.F*q[1]/q[2]];
function pr(c:Cam,P:V3):Pt|null{const q=toCam(c,P);return q[2]<NEAR?null:scr(c,q);}
function polyP(c:Cam,pts:V3[]):Pt[]{const q=pts.map(p=>toCam(c,p)),out:V3[]=[];
 for(let i=0;i<q.length;i++){const a=q[i],b=q[(i+1)%q.length],ia=a[2]>=NEAR,ib=b[2]>=NEAR;if(ia)out.push(a);if(ia!==ib){const k=(NEAR-a[2])/(b[2]-a[2]);out.push([a[0]+(b[0]-a[0])*k,a[1]+(b[1]-a[1])*k,NEAR]);}}
 return out.map(p=>scr(c,p));}
function seg3(c:Cam,a:V3,b:V3,wm:number,out:Path2D){let qa=toCam(c,a),qb=toCam(c,b);if(qa[2]<NEAR&&qb[2]<NEAR)return;
 const cut=(p:V3,q:V3):V3=>{const k=(NEAR-p[2])/(q[2]-p[2]);return[p[0]+(q[0]-p[0])*k,p[1]+(q[1]-p[1])*k,NEAR];};if(qa[2]<NEAR)qa=cut(qa,qb);else if(qb[2]<NEAR)qb=cut(qb,qa);
 const A=scr(c,qa),Bp=scr(c,qb),wa=Math.max(1.1,c.F*wm/qa[2]/2),wb=Math.max(1.1,c.F*wm/qb[2]/2),dx=Bp[0]-A[0],dy=Bp[1]-A[1],l=Math.hypot(dx,dy)||1,nx=-dy/l,ny=dx/l;
 out.moveTo(A[0]+nx*wa,A[1]+ny*wa);out.lineTo(Bp[0]+nx*wb,Bp[1]+ny*wb);out.lineTo(Bp[0]-nx*wb,Bp[1]-ny*wb);out.lineTo(A[0]-nx*wa,A[1]-ny*wa);out.closePath();}
const inView=(v:View,p:Pt,m=0)=>Math.abs(p[0])<v.hx+m&&Math.abs(p[1])<v.hy+m;
function quadP(c:Cam,q:V3[],minDepth=18):Pt[]|null{let lo=Infinity;for(const p of q)lo=Math.min(lo,toCam(c,p)[2]);if(lo<minDepth)return null;return q.map(p=>scr(c,toCam(c,p)));}
const addPoly=(p:Path2D,q:Pt[])=>{if(q.length>2)p.addPath(polyPath(q,true));};
/** a ground ring (ellipse rx × rz metres) as a ribbon path */
function groundRing(c:Cam,x:number,z:number,rx:number,rz:number,wm:number,seed:number,o:{dashed?:boolean;minW?:number}={}):Path2D|null{const pts:Pt[]=[];for(let i=0;i<40;i++){const a=i/40*TAU,q=pr(c,[x+Math.cos(a)*rx,.02,z+Math.sin(a)*rz]);if(q)pts.push(q);}
 if(pts.length<30)return null;const d=toCam(c,[x,0,z])[2],w=Math.max(o.minW??3,c.F*wm/Math.max(1,d));const gaps:[number,number][]=[];if(o.dashed)for(let i=0;i<12;i++)gaps.push([i/12+.04,i/12+.075]);
 return ribbon(pts,w,{close:true,seed,taper:0,wobble:.8,gaps});}

// ---------------------------------------------------------------- Lusail at night: a round bowl, two tiers, the roof ring and its floodlight band
const CX=52.5,NS=64;
function rim(th:number,d:number,y:number):V3{const c=Math.cos(th),s=Math.sin(th);return[CX+(60+d)*Math.sign(c)*Math.pow(Math.abs(c),.55),y,(43+d)*Math.sign(s)*Math.pow(Math.abs(s),.55)];}
const LOW=(b:number):[number,number]=>[2+22*b,1.6+12*b],UP=(b:number):[number,number]=>[25+22*b,16.5+17*b];
type Bowl={low:V3[][];up:V3[][];roof:V3[][];band:V3[][];seats:{P:V3;h:number}[];lamps:V3[]};
const BOWL:Bowl=(()=>{const o:Bowl={low:[],up:[],roof:[],band:[],seats:[],lamps:[]};
 for(let i=0;i<NS;i++){const a=i/NS*TAU,b=(i+1)/NS*TAU,Q=(f:(u:number)=>[number,number],u0:number,u1:number):V3[]=>{const[d0,y0]=f(u0),[d1,y1]=f(u1);return[rim(a,d0,y0),rim(b,d0,y0),rim(b,d1,y1),rim(a,d1,y1)];};
  o.low.push(Q(LOW,0,1));o.up.push(Q(UP,0,1));
  o.roof.push([rim(a,44,36),rim(b,44,36),rim(b,70,40),rim(a,70,40)]);
  o.band.push([rim(a,44,34.4),rim(b,44,34.4),rim(b,44,36.2),rim(a,44,36.2)]);
  o.lamps.push(rim(a+.5/NS*TAU,44,35.3));
  for(const [f,rows] of [[LOW,9],[UP,8]] as [(u:number)=>[number,number],number][])for(let r=0;r<rows;r++)for(let k=0;k<3;k++){const h=hash(i*977+r*31+k*7+rows*500,19);if(h<.12)continue;
   const[d,y]=f((r+.5)/rows);o.seats.push({P:rim((i+(k+.5+(hash(i+r*13+k,5)-.5)*.5)/3)/NS*TAU,d,y+.4),h});}}
 return o;})();
/** the night sky, the bowl, the crowd (roar lifts the marks; flash = camera flashes) */
function stadium(s:Sheet,c:Cam,v:View,t:number,o:{roar?:number;flash?:number}={}){
 const{roar=0,flash=0}=o;
 s.fill(K,rectPath(-1e4,-1e4,2e4,2e4),.92);s.tone(B,rectPath(-1e4,-1e4,2e4,2e4),.3);
 const low=new Path2D(),up=new Path2D(),roof=new Path2D(),band=new Path2D();
 for(let i=0;i<NS;i++){const add=(q:V3[],p:Path2D)=>{const r=quadP(c,q);if(r)p.addPath(polyPath(r,true));};add(BOWL.low[i],low);add(BOWL.up[i],up);add(BOWL.roof[i],roof);add(BOWL.band[i],band);}
 s.knockout(low,.8);s.tone(B,low,.5);s.tone(K,low,.3);
 s.knockout(up,.8);s.tone(B,up,.45);s.tone(K,up,.45);
 // the crowd: mostly Argentina's sky blue and white, some gold, a little red; one mark per seat group, sized by distance
 const inks=[new Path2D(),new Path2D(),new Path2D(),new Path2D(),new Path2D()];
 for(const q of BOWL.seats){const d=toCam(c,q.P);if(d[2]<18)continue;const p=scr(c,d);if(!inView(v,p))continue;const z=clamp(c.F*.5/d[2],2,13),lift=roar>0?roar*z*1.4*Math.max(0,Math.sin(t*11+q.h*TAU)):0;
  const ink=q.h<.42?0:q.h<.72?1:q.h<.82?2:q.h<.9?3:4;inks[ink].rect(p[0]-z/2,p[1]-z*.7-lift,z,z*1.3);}
 s.knockout(inks[0],.8);s.fill(B,inks[1],.6);s.fill(Y,inks[2],.85);s.fill(R,inks[3],.8);s.fill(K,inks[4],.7);
 s.knockout(roof);s.tone(K,roof,.7);s.tone(B,roof,.5);
 s.knockout(band);s.fill(Y,band,.55);
 const lamps=new Path2D();for(const L of BOWL.lamps){const d=toCam(c,L);if(d[2]<18)continue;const g=scr(c,d);if(!inView(v,g))continue;const z=clamp(c.F*.9/d[2],3,16);lamps.addPath(polyPath(blob(g[0],g[1],z,z*.55,3,{amp:.05,n:10}),true));}
 s.knockout(lamps);
 if(flash>0){const p=new Path2D(),T12=Math.floor(t*12);for(let i=0;i<16;i++){const q=BOWL.seats[Math.floor(hash(i*17+T12*101,3)*BOWL.seats.length)],d=toCam(c,q.P);if(d[2]<18)continue;const g=scr(c,d);if(!inView(v,g))continue;const z=8+14*flash*hash(i,T12);
  p.addPath(polyPath([[g[0]-z,g[1]],[g[0],g[1]-z*.35],[g[0]+z,g[1]],[g[0],g[1]+z*.35]],true));p.addPath(polyPath([[g[0],g[1]-z],[g[0]+z*.3,g[1]],[g[0],g[1]+z],[g[0]-z*.3,g[1]]],true));}s.knockout(p);s.fill(Y,p,.95);}
}
/** grass under floodlights (yellow × blue, a navy night screen) with mowing stripes, LED boards, paper lines, both goals */
function ground(s:Sheet,c:Cam,o:{bulge?:number;goalLater?:boolean}={}){
 const sur=polyP(c,[[-9,0,-40],[114,0,-40],[114,0,40],[-9,0,40]]);if(sur.length>2){const p=polyPath(sur,true);s.knockout(p);s.tone(B,p,.5);s.tone(K,p,.35);}
 const g=polyP(c,[[-6,0,-38],[111,0,-38],[111,0,38],[-6,0,38]]);if(g.length<3)return;const gp=polyPath(g,true);
 s.knockout(gp);s.fill(Y,gp,.95);s.tone(B,gp,.84);s.tone(K,gp,.1);
 const st=new Path2D();for(let k=0;k<20;k+=2)addPoly(st,polyP(c,[[k*5.25,0,-38],[(k+1)*5.25,0,-38],[(k+1)*5.25,0,38],[k*5.25,0,38]]));s.tone(K,st,.12);
 const bd=new Path2D(),pn=new Path2D();
 for(const q of [polyP(c,[[-4,0,-37],[109,0,-37],[109,.9,-37],[-4,.9,-37]]),polyP(c,[[108.5,0,-36],[108.5,0,36],[108.5,.9,36],[108.5,.9,-36]]),polyP(c,[[-3.5,0,36],[-3.5,0,-36],[-3.5,.9,-36],[-3.5,.9,36]])])addPoly(bd,q);
 for(let k=0;k<18;k++){const x=-2+k*6.2;addPoly(pn,polyP(c,[[x,.25,-36.95],[x+3.4,.25,-36.95],[x+3.4,.65,-36.95],[x,.65,-36.95]]));}
 for(let k=0;k<11;k++){const z=-34+k*6.4;addPoly(pn,polyP(c,[[108.45,.25,z],[108.45,.25,z+3.4],[108.45,.65,z+3.4],[108.45,.65,z]]));}
 s.knockout(bd);s.fill(R,bd,.9);s.tone(K,bd,.2);s.knockout(pn,.85);
 const ln=new Path2D(),L=(a:V3,b:V3)=>seg3(c,a,b,.12,ln);
 for(let k=0;k<8;k++){L([k*13.125,0,-34],[(k+1)*13.125,0,-34]);L([k*13.125,0,34],[(k+1)*13.125,0,34]);}
 for(let k=0;k<4;k++){const z0=-34+k*17,z1=z0+17;L([105,0,z0],[105,0,z1]);L([0,0,z0],[0,0,z1]);L([52.5,0,z0],[52.5,0,z1]);}
 const circ=(cx:number,cz:number,r:number,a0=0,a1=TAU,n=28)=>{for(let i=0;i<n;i++){const u0=a0+(a1-a0)*i/n,u1=a0+(a1-a0)*(i+1)/n;L([cx+Math.cos(u0)*r,0,cz+Math.sin(u0)*r],[cx+Math.cos(u1)*r,0,cz+Math.sin(u1)*r]);}};
 circ(52.5,0,9.15);circ(52.5,0,.1,0,TAU,6);
 for(const [gx,d] of [[105,-1],[0,1]] as [number,number][]){const bx=gx+d*16.5,sx=gx+d*5.5;L([gx,0,-20.16],[bx,0,-20.16]);L([bx,0,-20.16],[bx,0,20.16]);L([bx,0,20.16],[gx,0,20.16]);L([gx,0,-9.16],[sx,0,-9.16]);L([sx,0,-9.16],[sx,0,9.16]);L([sx,0,9.16],[gx,0,9.16]);
  const a=Math.acos(5.5/9.15);circ(gx+d*11,0,9.15,d<0?Math.PI-a:-a,d<0?Math.PI+a:a,10);circ(gx+d*11,0,.08,0,TAU,6);}
 s.knockout(ln);
 goal3(s,c,0,-1,0);
 if(!o.goalLater)goal3(s,c,105,1,o.bulge??0);
}
/** a goal at X: posts at z ±3.66, bar 2.44, net 2 m deep behind it (d = direction of the net); bulge pushes the back net out */
function goal3(s:Sheet,c:Cam,X:number,d:number,bulge:number){
 const z0=-3.66,z1=3.66,H=2.44,bk=X+d*(2+.55*bulge);
 const planes:V3[][]=[[[X,0,z0],[X,H,z0],[bk,1.9,z0],[bk,0,z0]],[[X,0,z1],[X,H,z1],[bk,1.9,z1],[bk,0,z1]],[[X,H,z0],[X,H,z1],[bk,1.9,z1],[bk,1.9,z0]],[[bk,0,z0],[bk,0,z1],[bk,1.9,z1],[bk,1.9,z0]]];
 const net=new Path2D();for(const P of planes)addPoly(net,polyP(c,P));
 s.knockout(net,.32);
 const mesh=new Path2D();
 for(let i=0;i<=12;i++){const z=lerp(z0,z1,i/12);seg3(c,[X,H,z],[bk,1.9,z],.025,mesh);seg3(c,[bk,1.9,z],[bk,0,z],.025,mesh);}
 for(let j=1;j<=5;j++){const y=1.9*j/6;seg3(c,[bk,y,z0],[bk,y,z1],.025,mesh);seg3(c,[X,y*H/1.9,z0],[bk,y,z0],.025,mesh);seg3(c,[X,y*H/1.9,z1],[bk,y,z1],.025,mesh);}
 s.fill(K,mesh,.75);
 const fr=new Path2D();seg3(c,[X,0,z0],[X,H,z0],.12,fr);seg3(c,[X,0,z1],[X,H,z1],.12,fr);seg3(c,[X,H,z0-.06],[X,H,z1+.06],.12,fr);
 const fo=new Path2D();seg3(c,[X,0,z0],[X,H,z0],.19,fo);seg3(c,[X,0,z1],[X,H,z1],.19,fo);seg3(c,[X,H,z0],[X,H,z1],.19,fo);s.stroke(K,fo,2.5,.9);s.knockout(fr);
}

