   runLine(s,c,MAC,tau,RX_RUN,sm(ms,is+.4,t,easeOut)*fade*(tau<RX_RUN?1:0),85);
   // "and Álvarez finds him": the pass arrow from Álvarez's boot into the space
   groundArrow(s,c,[THRU_PS[0],THRU_PS[2]],MAC_RX,sm(aa-.1,fh+.1,t,easeOut)*fade,86);
   contactSpark(s,c,THRU_PS,tau,THRU,87);
