const DEMO:Dk[]=[
 {style:RUN_ST,keys:[[0,5.2,-2.4],[2.4,5.6,-2.6],[3.6,6.4,-2.9],[4.4,7.8,-3.1],[5.15,10,-3.1],[6.5,13.2,-3.2],[8,16,-3.3]]},
 {style:DEF_ST(91,{hair:[K,.9]}),keys:[[0,7.6,-1.4],[D1A,7.7,-2.8],[D2A-.4,7.6,-1.1],[4.6,7.5,-.2],[8,7.7,.3]]},
 {style:DEF_ST(92,{skin:SKIN_M,hairStyle:'ponytail',hair:[K,.95]}),keys:[[0,7.8,-4.1],[D1A+.3,7.9,-5.6],[D2A,7.8,-5.2],[4.6,7.8,-5.3],[8,7.9,-5]]},
];
const DTAB=DEMO.map(d=>{const X:number[]=[],Z:number[]=[],D:number[]=[];let dd=0,px=0,pz=0;for(let i=0;i<=420;i++){const[x,z]=herm(d.keys,i*.02);if(i)dd+=Math.hypot(x-px,z-pz);X.push(x);Z.push(z);D.push(dd);px=x;pz=z;}return{X,Z,D};});
const dS=(arr:number[],mu:number)=>{const u=clamp(mu/.02,0,arr.length-1),i=Math.floor(u),f=u-i;return i+1<arr.length?lerp(arr[i],arr[i+1],f):arr[i];};
