 const tr=new Path2D(),hd=new Path2D();for(let i=0;i<26;i++){const z=-58+i*3.6+hash(i,3)*2,q=pr(c,[62,0,z]);if(!q||!inView(v,q,400))continue;const sc=c.F/Math.max(1,toCam(c,[62,0,z])[2]),hgt=(8+hash(i,4)*6)*sc;tr.addPath(polyPath(blob(q[0],q[1]-hgt*.62,hgt*.42,hgt*.55,i+9,{amp:.1,n:18}),true));}
 addPoly(hd,polyP(c,[[56,0,-60],[56,0,30],[56,1.6,30],[56,1.6,-60]]));
 s.knockout(tr);s.fill(Y,tr,.75);s.tone(B,tr,.9);s.tone(K,tr,.45);s.fill(Y,hd,.6);s.tone(K,hd,.55);
 const ln=new Path2D();seg3(c,[-40,0,5],[60,0,5],.12,ln);seg3(c,[-3,0,-40],[-3,0,5],.12,ln);s.knockout(ln);
 const cn=new Path2D();for(const[x,z] of [[-2,2],[-2,-8],[14,2],[14,-8],[6.5,3],[6.5,-9]] as [number,number][]){const a=pr(c,[x-.18,0,z]),b=pr(c,[x+.18,0,z]),tp=pr(c,[x,.32,z]);if(a&&b&&tp)cn.addPath(polyPath([a,tp,b],true));}
