  const lane=(a:[number,number],b:[number,number],m0:number,m1:number,seed:number)=>{const w=sm(m0-.3,m0,mu)*(1-sm(m1,m1+.5,mu));if(w>0)groundArrow(s,c,a,b,Math.min(1,w*1.4),seed,{ink:B,dashed:true,wm:.12});};
