  const who:{w:'you'|'mate'|number;x:number;z:number;st:AthleteStyle}[]=[{w:'you',x:YOU_P[0],z:YOU_P[1],st:YOU_ST},{w:'mate',x:MATE_P[0],z:MATE_P[1],st:MATE_ST},...DEMO.map((d,k)=>({w:k,x:dPos(k,mu)[0],z:dPos(k,mu)[1],st:d.style}))];
